//! Real same-host completion/current-owner and strict delivery controls.
use super::*;use std::io;use dq_analyze::workspace_fold_policy::Policy;use crate::policy_request::WorkspaceAuxiliaryQuestion as Q;
#[path="../../../../analyze/fixtures/native-workspace-fold/fixture.rs"]mod initial;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod complete_config;
const POLICIES:&[Policy]=&[Policy::Tracked,Policy::TrackedTests,Policy::StateSchema,Policy::Lifecycle,Policy::Loot,Policy::InstanceList,Policy::Cache,Policy::OwnershipForms,Policy::Api,Policy::Fields,Policy::Appearance];
fn prepared(policy:Policy)->(crate::runner_host::BuildHost,crate::request::BuildRequest,PathBuf){let(mut host,mut request,root)=super::analysis_context_tests::fixture("/proc/unused_initial()\n    return 1\n");std::fs::remove_file(root.join("code/probe.dm")).unwrap();for(relative,bytes)in initial::files(policy,if policy==Policy::TrackedTests{"maps_tests"}else{initial::cases(policy)[0]}).unwrap(){let target=root.join(relative);std::fs::create_dir_all(target.parent().unwrap()).unwrap();std::fs::write(target,bytes).unwrap();}complete_config::complete(&root.join("tools/ci/lint_scopes.toml"));request.policy_inputs.as_mut().unwrap().workspace_auxiliary=match policy.tracked(){Some(false)=>vec![Q::Tracked],Some(true)=>vec![Q::TrackedTests],None=>Vec::new()};super::analysis_context_tests::run(&mut host,&request);(host,request,root)}
#[test]fn actual_all_completed_policy_families_page_real_outputs_preserve_hard_contract_and_warm_owner(){for policy in POLICIES{let(mut host,request,root)=prepared(*policy);let query_db=Arc::clone(host.query_db());let first=super::analysis_context_tests::current(&host,|snapshot|{let mut cursor=None;let mut whole=Vec::new();loop{let mut bytes=Vec::new();snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&[policy.name().into()],cursor.as_ref(),1,&snapshot.tree,&mut bytes).unwrap();let row:serde_json::Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(row["row"],"source_native_workspace_policy_report");assert_eq!(row["lint_whitelist"],serde_json::json!([policy.name()]));for item in row["items"].as_array().unwrap(){match item["kind"].as_str().unwrap(){"hard_site"=>{assert!(policy.message_only());assert!(!item["site"]["msg"].as_str().unwrap().is_empty());assert!(item.get("source_text").is_none());},"site"=>{assert!(!policy.message_only());assert!(item["source_text"].is_string());},_=>()}}let query=crate::daemon::query::SourceQuery::NativeWorkspacePolicyReportPage{root:root.clone(),configuration:root.join("tools/ci/lint_scopes.toml"),lints:vec![policy.name().into()],cursor:cursor.clone(),limit:1};let reply=crate::daemon::query::QueryReply{schema:"dm-session-query-v1".into(),revision:format!("{:032x}",snapshot.tree.identity()),complete:false,coverage:"partial".into(),query_count:0,source_query_count:1,source_revision:Some(format!("{:032x}",snapshot.source_revision)),policy_revision:Some(format!("{:032x}",snapshot.policy_revision.unwrap())),snapshot_outcome:"analyzed".into(),last_request_outcome:"analyzed".into(),publication_pair:None,jsonl:String::from_utf8(bytes).unwrap()};crate::daemon::query::validate_workspace_report_delivery(&reply,&[query.clone()]).unwrap();if cursor.is_none(){let actual=row["aggregate_id"].as_str().unwrap();let mut wrong=actual.to_owned();wrong.replace_range(0..1,if actual.starts_with('0'){"1"}else{"0"});let foreign=serde_json::from_value(serde_json::json!({"aggregate_id":wrong,"offset":0})).unwrap();let mut rejected=Vec::new();let error=snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&[policy.name().into()],Some(&foreign),1,&snapshot.tree,&mut rejected).unwrap_err();assert_eq!(error.kind(),io::ErrorKind::InvalidInput);assert!(rejected.is_empty());}if !policy.emits_notes()&&!row["items"].as_array().unwrap().is_empty(){let mut forged=reply.clone();let mut wrong=row.clone();wrong["items"][0]=serde_json::json!({"lint":policy.name(),"kind":"note","text":"forged nonissuing family note"});forged.jsonl=format!("{wrong}\n");assert!(crate::daemon::query::validate_workspace_report_delivery(&forged,&[query.clone()]).is_err());}let mut forged=reply.clone();let mut wrong=row.clone();wrong["row"]=serde_json::json!("source_native_workspace_raw_report");forged.jsonl=format!("{wrong}\n");assert!(crate::daemon::query::validate_workspace_report_delivery(&forged,&[query]).is_err());whole.extend(row["items"].as_array().unwrap().iter().cloned());if row["next_cursor"].is_null(){break}cursor=Some(serde_json::from_value(row["next_cursor"].clone()).unwrap());}assert!(whole.iter().any(|item|matches!(item["kind"].as_str(),Some("site"|"hard_site"))),"actual first old fixture must trigger {policy:?}");whole});let before=query_db.db().stats(dm_query::Kind(4)).computed;super::analysis_context_tests::run(&mut host,&request);super::analysis_context_tests::current(&host,|snapshot|{let mut bytes=Vec::new();snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&[policy.name().into()],None,128,&snapshot.tree,&mut bytes).unwrap();let row:serde_json::Value=serde_json::from_slice(&bytes).unwrap();assert!(row["next_cursor"].is_null(),"fixture output exceeds full test page");assert_eq!(row["items"],serde_json::json!(first));});assert_eq!(query_db.db().stats(dm_query::Kind(4)).computed,before,"report refold shares original body owner");}}
#[test]fn actual_complete_policy_writer_keeps_first_1450_over_late_cancel_and_recovers(){for policy in POLICIES{let(host,_,root)=prepared(*policy);super::analysis_context_tests::current(&host,|snapshot|{struct Fail(crate::daemon::control::Cancellation);impl io::Write for Fail{fn write(&mut self,_:&[u8])->io::Result<usize>{self.0.cancel();Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let cancellation=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(cancellation.clone(),std::time::Instant::now()+std::time::Duration::from_secs(60));let actual=snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&[policy.name().into()],None,128,&snapshot.tree,&mut Fail(cancellation)).unwrap_err();assert_eq!(actual.raw_os_error(),Some(1450));drop(binding);let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||snapshot.with_native_workspace_fold_report(&snapshot.tree,*policy,|_,_,_|->io::Result<()>{panic!("actual report consumer unwind")})));assert!(panic.is_err());let mut bytes=Vec::new();snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&[policy.name().into()],None,128,&snapshot.tree,&mut bytes).unwrap();});}}
#[test]fn actual_tracked_public_report_refuses_other_selected_semantic_role_before_consumer(){let(host,_,root)=prepared(Policy::Tracked);super::analysis_context_tests::current(&host,|snapshot|{let mut called=false;assert!(snapshot.with_native_workspace_fold_report(&snapshot.tree,Policy::TrackedTests,|_,_,_|{called=true;Ok(())}).is_err());assert!(!called);let mut bytes=Vec::new();assert!(snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&["tracked_unported".into()],None,128,&snapshot.tree,&mut bytes).is_err());assert!(bytes.is_empty());});}

#[test]fn actual_complete_policy_public_dispatch_rejects_missing_unselected_lists_before_any_policy_job(){use crate::daemon::query::{self,QueryRequest,SourceQuery};let(mut host,request,root)=super::analysis_context_tests::fixture("/proc/preflight_probe()\n    return 1\n");std::fs::write(root.join("tools/ci/lint_scopes.toml"),"[lint.state_schema]\n").unwrap();super::analysis_context_tests::run(&mut host,&request);let state=host.query_state();let held=state.lock().unwrap();let snapshot=held.snapshot.as_ref().unwrap();let before=host.query_db().db().stats(dm_query::Kind(12)).computed;for policy in POLICIES{let query=QueryRequest{analysis_context:request.policy_inputs.as_ref().unwrap().analysis_context,timeout_seconds:Some(60),project:request.project.clone(),defines:Default::default(),engine_template:None,bootstrap_catalog:false,expected_revision:Some(format!("{:032x}",snapshot.tree.identity())),expected_source_revision:Some(format!("{:032x}",snapshot.source_revision)),expected_policy_revision:Some(format!("{:032x}",snapshot.policy_revision.unwrap())),queries:Vec::new(),source_queries:vec![SourceQuery::NativeWorkspacePolicyReportPage{root:root.clone(),configuration:root.join("tools/ci/lint_scopes.toml"),lints:vec![policy.name().into()],cursor:None,limit:128}]};let actual=query::evaluate_snapshot(&query,&snapshot.tree,&held).unwrap_err();assert_eq!(actual.kind(),io::ErrorKind::InvalidInput);assert!(actual.to_string().contains("lint_scopes.toml:")&&actual.to_string().contains("is missing"),"{policy:?}: {actual}");assert_eq!(host.query_db().db().stats(dm_query::Kind(12)).computed,before);}}

#[test]fn actual_tracked_public_report_cannot_substitute_included_fixed_manifest_for_caller_main(){let(mut host,mut request,root)=prepared(Policy::Tracked);std::fs::write(root.join("main.dme"),b"#include \"deepquarry.dme\"\n").unwrap();request.project=root.join("main.dme");super::analysis_context_tests::run(&mut host,&request);super::analysis_context_tests::current(&host,|snapshot|{snapshot.with_original_tracked_policy(false,|_|Ok(())).unwrap();let mut output=Vec::new();assert!(snapshot.write_native_workspace_policy_report_page(&root,&root.join("tools/ci/lint_scopes.toml"),&["tracked".into()],None,128,&snapshot.tree,&mut output).is_err());assert!(output.is_empty());});}
